"""Native exact host/key lanes and synchronous registry transactions."""
import ast
from tools.generate_hia_mcp_job_bridge_common import authored
SOURCE='\ndef advance(s:readbuf,o:mutbuf,w:mutbuf) -> u32:\n    phase=get(w,0)\n    result=get(w,8)\n    if phase==0:\n        if get(w,264)==0 or get(w,TX_LANE)!=0:\n            return 0\n        at=text_lane(w,TX_NAME)\n        at=cp(w,S_HOST,at)\n        store(w,at,46)\n        at=cp(w,S_JOB_KEY,at+1)\n        if at-TX_NAME>255:\n            return 0\n        store(w,at,0)\n        return call(o,w,1,257,get(w,1200),TX_NAME,657474,384,0,0,12)\n    if phase==1:\n        if failed(result) or result<3:\n            return 0\n        put(w,TX_LANE,result)\n        return call(o,w,2,5,result,TX_STAT,0,0,0,0,12)\n    if phase==2:\n        if failed(result) or safe_regular(w,TX_STAT,1)==False or get(w,TX_STAT+48)!=0:\n            return 0\n        copy_state(w,TX_STAT,TX_STAMP,144)\n        return call(o,w,3,262,get(w,1200),TX_NAME,TX_STAT,256,0,0,60)\n    if phase==3:\n        if failed(result) or safe_regular(w,TX_STAT,1)==False or same_stamp(w,TX_STAT,TX_STAMP)==False:\n            return 0\n        lock(w,2)\n        return call(o,w,6,72,get(w,1216),6,TX_LOCK,0,0,0,48)\n    if phase==6:\n        if result==NEG4:\n            return call(o,w,6,72,get(w,1216),6,TX_LOCK,0,0,0,48)\n        if failed(result):\n            return 0\n        put(w,TX_GLOBAL,0)\n        lock(w,1)\n        return call(o,w,4,72,get(w,TX_LANE),7,TX_LOCK,0,0,0,48)\n    if phase==4:\n        if result==NEG4:\n            return call(o,w,4,72,get(w,TX_LANE),7,TX_LOCK,0,0,0,48)\n        if failed(result):\n            return 0\n        return call(o,w,5,262,get(w,1200),TX_NAME,TX_STAT,256,0,0,60)\n    if phase==5:\n        if failed(result) or safe_regular(w,TX_STAT,1)==False or same_stamp(w,TX_STAT,TX_STAMP)==False:\n            return 0\n        put(w,TX_MODULE,2)\n        put(w,TX_PHASE,108)\n        return enter(w,13,30)\n    if phase==20:\n        if get(w,TX_GLOBAL)!=1:\n            return 0\n        lock(w,2)\n        return call(o,w,21,72,get(w,1216),6,TX_LOCK,0,0,0,48)\n    if phase==21:\n        if result==NEG4:\n            return call(o,w,21,72,get(w,1216),6,TX_LOCK,0,0,0,48)\n        if failed(result):\n            return 0\n        put(w,TX_GLOBAL,0)\n        return resume(w)\n    if phase==30:\n        if get(w,TX_GLOBAL)!=0:\n            return 0\n        lock(w,1)\n        return call(o,w,31,72,get(w,1216),7,TX_LOCK,0,0,0,48)\n    if phase==31:\n        if result==NEG4:\n            return call(o,w,31,72,get(w,1216),7,TX_LOCK,0,0,0,48)\n        if failed(result):\n            return 0\n        put(w,TX_GLOBAL,1)\n        return resume(w)\n    if phase==40:\n        fd=get(w,TX_LANE)\n        if fd==0 or fd==NONE:\n            return 0\n        lock(w,2)\n        return call(o,w,41,72,fd,6,TX_LOCK,0,0,0,48)\n    if phase==41:\n        fd=get(w,TX_LANE)\n        put(w,TX_LANE,NONE)\n        return call(o,w,42,3,fd,0,0,0,0,0,0)\n    if phase==42:\n        return resume(w)\n    return 0\n\ndef lock(w:mutbuf,kind:u64) -> u64:\n    put(w,TX_LOCK,kind)\n    put(w,TX_LOCK+8,0)\n    put(w,TX_LOCK+16,0)\n    put(w,TX_LOCK+24,0)\n    return 0\n\ndef resume(w:mutbuf) -> u32:\n    return enter(w,get(w,TX_MODULE),get(w,TX_PHASE))\n'
def source():
    return authored(ast.unparse(ast.parse(SOURCE)), text={'lane': '.hia-start-'})
